import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CCXDMzJr.js";const u=JSON.parse('{"title":"第 16 章 代理预设、目标与子代理","description":"","frontmatter":{},"headers":[],"relativePath":"ch16-preset-goal-subagent.md","filePath":"ch16-preset-goal-subagent.md","lastUpdated":null}'),l={name:"ch16-preset-goal-subagent.md"};function c(d,e,n,r,i,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="第-16-章-代理预设、目标与子代理" tabindex="-1">第 16 章 代理预设、目标与子代理 <a class="header-anchor" href="#第-16-章-代理预设、目标与子代理" aria-label="Permalink to &quot;第 16 章 代理预设、目标与子代理&quot;">​</a></h1><p>本章覆盖 dsh 的&quot;会话层&quot;高级机制：<strong>agent preset</strong>（每个会话的能力组合）、<strong>goal</strong>（同会话目标循环）、<strong>subagent</strong>（子代理接缝）、以及 plan/skill/compaction 等扩展。</p><h2 id="_16-1-agent-preset-会话层组装" tabindex="-1">16.1 agent preset：会话层组装 <a class="header-anchor" href="#_16-1-agent-preset-会话层组装" aria-label="Permalink to &quot;16.1 agent preset：会话层组装&quot;">​</a></h2><p>第 9 章讲过 profile/bundle 是<strong>启动层</strong>组装（决定&quot;这个进程由哪些行组成&quot;）。preset 是<strong>会话层</strong>组装（决定&quot;每个会话看到哪些工具与提示词段落&quot;）——两者正交。一个进程可以同时运行多个组装方式不同的 agent。</p><h3 id="目录布局" tabindex="-1">目录布局 <a class="header-anchor" href="#目录布局" aria-label="Permalink to &quot;目录布局&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$DSH_HOME/.agent-presets/&lt;id&gt;/     # 用户本地 preset</span></span>
<span class="line"><span>apps/cli/config/agent-presets/     # 部署交付的 preset（standard、code、cordis、minimal…）</span></span>
<span class="line"><span>├── agent.cordis.yml               # 组合文件：一份 Cordis 插件行列表</span></span>
<span class="line"><span>└── preset.yml                     # 显示元数据：name/description/order</span></span></code></pre></div><ul><li><strong>目录名即 preset id</strong>，必须匹配 <code>^[a-z0-9][a-z0-9-]*$</code>——id 会成为路径段，这是<strong>包含边界</strong>（<code>..</code>、分隔符会让组合文件落到授权根之外）；</li><li><code>preset.yml</code> <strong>只承载显示文本</strong>：<code>id</code>=目录名、<code>trust</code>=所在根（<code>system|user</code>），不可在元数据里改写——否则本地 preset 可伪装成官方件；</li><li>发现不记忆化：<code>list()</code>/<code>resolve()</code> 每次重读根——进程运行期间新写的 preset 立即可见，被删者下一次消失；</li><li><strong>broken preset 保留在 roster 上</strong>（目录占着 id，隐藏了就无可看可删），但每个挂载路径都前置拒绝它（<code>resolveMountable</code> 在 loader 之前就抛 <code>PresetMountError</code>）。</li></ul><h3 id="standing-mount-每进程一份组合" tabindex="-1">standing mount：每进程一份组合 <a class="header-anchor" href="#standing-mount-每进程一份组合" aria-label="Permalink to &quot;standing mount：每进程一份组合&quot;">​</a></h3><p><strong>最核心的设计决策：一个 preset 是每进程一份组合，而不是每会话一份</strong>（设计笔记 <code>2026-08-08-per-preset-standing-mounts.md</code>）。原因：三个 host 读取端依赖&quot;静态注册面&quot;（cold <code>session.history</code> 的 presenter、projections 块、Typert 网关的 goals 解析）——每会话挂载会破坏它们。</p><ul><li><code>ensureStanding(preset)</code>：单飞行（single-flight）——两个 agent 竞用首用共享一份组合；</li><li>挂载 scope key 是 <code>{ agentPreset: preset.id }</code>；</li><li><strong>文件戳（stamp）</strong>：<code>compositionStamp = mtimeMs + size</code>——编辑组合文件会启动下一代 ensureStanding；<strong>已加入的会话保留其代次</strong>；被取代的代次只在整树 teardown 回收；</li><li><code>mount(agentCtx, id)</code>：<strong>唯一受支持的调用点是 agent factory 的 <code>setup(agentCtx)</code> hook</strong>——只有在这里，join 是在 agent 尚未发布时安装的，组合被拒绝可整体回滚创建；</li><li><code>composeFrom(agentCtx, parentCtx)</code>：子 agent <strong>加入父已运行的那份同一 standing 组合</strong>（不是 re-resolve preset）——同一代插件对象/工具注册/提示段落；同步、无组合失败模式，in-process 子代理驱动在同步 setup 内使用；</li><li><code>recompose(agentCtx, id)</code>：re-link 到另一 preset——parent re-link 而非 unmount（standing 共享且持久，旧组合留给其它 agent）；仅当 agent 还没产出时合法（调用方自查）。</li></ul><h3 id="挂载的防护审计" tabindex="-1">挂载的防护审计 <a class="header-anchor" href="#挂载的防护审计" aria-label="Permalink to &quot;挂载的防护审计&quot;">​</a></h3><p><code>mountPreset</code> 把组合子 Include（<code>PresetTree</code>）挂到 agent scope 下，在两个 guard 上 fail-loud：</p><ol><li><strong><code>inactiveRows</code></strong>：仍在等待组合未提供的服务的行（<code>fiber.inject</code> 里 <code>ctx.get</code> 为 undefined 的名字）→ 逐行报诊断并 reject；</li><li><strong><code>leakedServices</code></strong>：某行把服务发布进 <strong>ROOT realm（无 isolate）</strong> → 该服务是进程全局而非每会话，第二个会话挂同一 preset 会撞 → reject 并列出泄漏名。</li></ol><p>另有四个防御性覆写：</p><ul><li><strong><code>PresetTree.import</code></strong>：裸包名从 harness 自己的 base 解析（本地 preset 在用户 home，Node 向上 <code>node_modules</code> 走不到 harness 依赖）；</li><li><strong><code>PresetTree.write</code> 覆写为空</strong>：preset 是输入，<strong>从不作为持久化目标</strong>——否则 Loader 会在销毁时把预设文件重写成 <code>[]</code>（首会话一结束就截断 shipped 组合）；</li><li><code>mounts</code> 集合按 fiber <code>uid === null</code> 观察式清理；</li><li><code>serviceForAgent(ctx, agent, name)</code>：浏览器 RPC 从外部请求&quot;关于某个 agent 的某服务&quot;时，穿过 entry-local realm 读到该 agent 的实例（只读地址）。</li></ul><h3 id="isolate-realm-preset-正确性的地基" tabindex="-1">isolate realm：preset 正确性的地基 <a class="header-anchor" href="#isolate-realm-preset-正确性的地基" aria-label="Permalink to &quot;isolate realm：preset 正确性的地基&quot;">​</a></h3><ul><li><strong>发布服务的行必须放进带 <code>isolate</code> realm 的 group</strong>（<code>cordis:group</code> + <code>isolate: { &lt;label&gt;: true }</code>）——不带则发布进 root realm = 进程全局，另一 preset 发布同名就撞；</li><li><strong>共享 realm label 不是选项</strong>：<code>provide()</code> 在第二个同 realm symbol 注册时 throw；label 联的是 REALM 而非实例；</li><li>隔离方向：realm 是&quot;组内可见、组外（含 host 与其它 agent scope）不可见&quot;的<strong>单向遮蔽</strong>；</li><li><strong>host-plane vs agent-plane 判据</strong>：一行若 host 行 <code>inject</code> 服务（inject 在任何 session 前解析、无可 key 的 agent），该服务必须留在 host composition；行发布全局服务/注册进程级单例（subagent 注册表、jobs、shell-env）也归 host-plane；而 planMode、workflowEngine 是 per-agent 的，用 entry-local realm 正确。</li></ul><h3 id="会话记录" tabindex="-1">会话记录 <a class="header-anchor" href="#会话记录" aria-label="Permalink to &quot;会话记录&quot;">​</a></h3><p><code>SessionHeader.agentPreset</code> 持久化&quot;从哪个 preset 组合&quot;——resume 恢复到不同组合会把模型再也无法执行的历史重放给它。创建后换 preset 经 <code>agent-preset/selected</code> 会话事件（log-only）；<code>resolveSessionPreset</code> 扫日志取<strong>最新一次</strong>选择（回放重建切换过的会话时不能只看创建时值）。</p><h2 id="_16-2-goal-同会话目标循环" tabindex="-1">16.2 goal：同会话目标循环 <a class="header-anchor" href="#_16-2-goal-同会话目标循环" aria-label="Permalink to &quot;16.2 goal：同会话目标循环&quot;">​</a></h2><p><code>packages/goal/*</code> 四包：<code>goal</code>（领域核心 <code>ctx.goals</code>）、<code>goal-round-driver</code>（自动续跑）、<code>tool-goal</code>（模型工具）、<code>command-goal</code>（人类 <code>/goal</code> 命令）。</p><p><strong>目标状态由会话日志的 <code>goal/change</code> 事件驱动</strong>（CAS 变更，自动满足&quot;模型可见 ⟺ 已持久化&quot;规则）：</p><ul><li><code>GoalId</code> 品牌化；<code>GoalRef { id, revision }</code> CAS 身份，每次 accepted 变更 revision+1；</li><li><code>GoalPhase = &#39;active&#39; | &#39;paused&#39; | &#39;blocked&#39; | &#39;complete&#39;</code>——<strong>phase 是持久化生命周期</strong>；<code>activation = &#39;armed&#39; | &#39;disarmed&#39;</code> 是<strong>进程内续跑资格</strong>——两者分离（会话恢复后目标需要 re-arm）；</li><li><code>GoalOperation = create|edit|pause|resume|complete|block|clear</code>；</li><li>变更载荷：<code>GoalSnapshotChangeMeta</code>（完整快照）或 <code>GoalClearChangeMeta</code>（clear tombstone）；</li><li>每轮续跑以 <code>{ kind: &#39;goal&#39;, goalId, revision, round }</code> 消息源合并进 <code>MessageSourceMap</code>；</li><li>会话事件 <code>goal/change</code> + Cordis 事件 <code>goal/changed</code>（emit、scope 过滤）；</li><li><code>GoalService extends TypertRemoteService</code>——<code>@Remote</code> 标记的方法同时是网关端点（UI 可从浏览器调用）；</li><li><code>goal-round-driver</code> 监听 <code>agent/*</code> 事件驱动继续：agent 静默后检查目标是否 armed、是否有剩余轮次，经 <code>agent.inject()</code> 注入下一轮续跑消息。</li></ul><h2 id="_16-3-subagent-子代理接缝" tabindex="-1">16.3 subagent：子代理接缝 <a class="header-anchor" href="#_16-3-subagent-子代理接缝" aria-label="Permalink to &quot;16.3 subagent：子代理接缝&quot;">​</a></h2><p><code>packages/subagent/subagent</code> 定义接缝，providers 一长串：</p><table tabindex="0"><thead><tr><th>Provider</th><th>形态</th></tr></thead><tbody><tr><td><code>fork-in-process</code> / <code>spawn-in-process</code> / <code>in-process-driver</code></td><td>进程内子代理（同步 setup 内 composeFrom 父组合）</td></tr><tr><td><code>subagent-acp</code></td><td>ACP（Agent Client Protocol）代理</td></tr><tr><td><code>subagent-claude-code</code> / <code>subagent-codex</code></td><td>外部产品委托</td></tr><tr><td><code>subagent-dsh-sdk</code></td><td>SDK 驱动</td></tr></tbody></table><p>消费者是 <code>tool-subagent</code> 系列工具（<code>subagent</code>、<code>subagent_report</code> 等）。接缝语义：<strong>从全新子 agent 到委托给另一产品的 turn</strong>，Provider 变化同样广泛——这正是&quot;可替换接缝&quot;的极致体现。子代理注册表是进程单例（provider 名只能注册一次），因此留 host-plane。</p><h2 id="_16-4-plan-skill-compaction-spill" tabindex="-1">16.4 plan / skill / compaction / spill <a class="header-anchor" href="#_16-4-plan-skill-compaction-spill" aria-label="Permalink to &quot;16.4 plan / skill / compaction / spill&quot;">​</a></h2><h3 id="plan-ctx-planmode" tabindex="-1">plan：ctx.planMode <a class="header-anchor" href="#plan-ctx-planmode" aria-label="Permalink to &quot;plan：ctx.planMode&quot;">​</a></h3><p><strong>没有 <code>ctx.plan</code></strong>——plan 服务是 <code>ctx.planMode</code>（<code>PlanModeController</code>）；模型侧退出是 <code>exit_plan_mode</code> 工具，人类侧是 <code>/plan</code> 命令；状态是对日志 <code>plan/mode</code> 事件的<strong>纯折叠</strong>。plan 模式在 preset 里用 entry-local realm（per-agent）。</p><h3 id="skill-ctx-skills" tabindex="-1">skill：ctx.skills <a class="header-anchor" href="#skill-ctx-skills" aria-label="Permalink to &quot;skill：ctx.skills&quot;">​</a></h3><p><strong>没有 <code>ctx.skill</code></strong>——服务是 <code>ctx.skills</code>（<code>SkillRegistry</code>）。技能<strong>不是</strong>经 <code>ctx.systemPrompt</code> 注入，而是以<strong>用户角色 <code>&lt;system-reminder&gt;</code> 目录消息</strong>在 <code>agent/pre-step</code> 注入（<code>tool-skill</code> 提供 <code>skill</code> 工具；<code>skill-filesystem</code> 提供技能文件系统支持）。</p><h3 id="compaction-会话压缩" tabindex="-1">compaction：会话压缩 <a class="header-anchor" href="#compaction-会话压缩" aria-label="Permalink to &quot;compaction：会话压缩&quot;">​</a></h3><p>compaction 是<strong>三维能力缝</strong>（<code>compaction/compaction</code> 定义，<code>compaction-basic</code> 实现，<code>compaction-tool-result-pruner</code> 裁剪工具结果）：</p><ul><li>向 <code>SessionEventMap</code> 声明合并 <code>compaction/start</code>/<code>summary</code>/<code>end</code> 事件（log-only）；</li><li>压缩通过 surface 的 <code>replace</code> 操作：摘要节点替换一批旧表面节点，<code>sourceEventSeqs</code> 完整列出被遮蔽节点；</li><li>触发：<code>/compact</code> 命令、自动策略、模型工具。</li></ul><h3 id="spill-溢出" tabindex="-1">spill：溢出 <a class="header-anchor" href="#spill-溢出" aria-label="Permalink to &quot;spill：溢出&quot;">​</a></h3><p><code>spill/spill</code> + <code>spill-local</code> + <code>spill-policy</code>：<strong>触发条件是单个工具结果超过 <code>maxInlineBytes</code> 上限</strong>（不是&quot;上下文整体太大&quot;）——超限结果被溢出到本地文件，模型可见处只放引用，避免把超大内容塞进上下文。<code>tools/code-dispatch-log</code> waterfall 提供 run_code 子派发日志的内容替换口。</p><h2 id="_16-5-会话周边" tabindex="-1">16.5 会话周边 <a class="header-anchor" href="#_16-5-会话周边" aria-label="Permalink to &quot;16.5 会话周边&quot;">​</a></h2><ul><li><strong>session-query</strong>：查询引擎（<code>tool-session-query</code> + SQLite 后端），Agent 可检索历史会话；</li><li><strong>session-projection</strong>：投影注册表 + 持久化缓存；</li><li><strong>session-title</strong>：会话标题生成（<code>ctx.sessionTitle</code> 唯一 provider，经 LLM）；</li><li><strong>workflow</strong>：工作流引擎缝（<code>workflow-worker-thread</code>、<code>tool-workflow</code>、<code>tool-ralph</code>）——多代理编排；</li><li><strong>commands</strong>：人类命令（<code>/goal</code>、<code>/plan</code>、<code>/compact</code>…），不经模型 turn 直接派发。</li></ul><h2 id="_16-6-小结" tabindex="-1">16.6 小结 <a class="header-anchor" href="#_16-6-小结" aria-label="Permalink to &quot;16.6 小结&quot;">​</a></h2><ul><li>preset 是会话层组装：每进程一份 standing mount、文件戳换代、mount 审计（inactive rows / leaked services）、isolate realm 是正确性地基；</li><li>goal 是同会话事件溯源目标：CAS 变更、phase 与 activation 分离、轮次驱动经 agent/inject 续跑；</li><li>subagent 是接缝：进程内/ACP/外部产品多种 provider，注册表留 host-plane；</li><li>plan（<code>ctx.planMode</code>）与 skill（<code>ctx.skills</code>）的命名与机制都和直觉不同，读代码时注意；</li><li>compaction 用 surface replace 压缩；spill 把大内容溢出到文件。</li></ul><p>至此，核心子系统全部解析完毕。下一部分进入 Web 客户端（第 17 章），然后是插件开发技巧（第 18-21 章）。</p>`,42)])])}const h=o(l,[["render",c]]);export{u as __pageData,h as default};
